        <div class="pp-size-hint">点击纹理立即应用到当前墙体{{ toAll ? '（及全部墙体）' : '' }}；「还原原始贴图」可恢复模型自带贴图</div>
      </div>

      <!-- 门窗素材（窗/门组合体的子部件 → 作用于所属整组） -->
      <div v-if="assetCtx" class="pp-sec">
        <div class="pp-sec-title">门窗素材（所属组件：{{ assetCtx.label }}）</div>
        <div v-if="!state.assets.loaded" class="pp-size-hint">素材库加载中…</div>
        <template v-else>
          <div class="pp-assets">
            <button v-for="a in assetList" :key="a.id" class="pp-asset" :class="{ on: currentAssetId === a.id }"
              @click="pickAsset(a.id)">{{ a.name }}</button>
          </div>
          <div v-if="currentAssetId" class="pp-asset-cur">
            当前素材：{{ currentAssetName }}
            <button class="pp-restore" @click="restoreAsset">恢复原始部件</button>
          </div>
          <div v-else class="pp-size-hint">点击素材替换整个{{ assetCtx.type === 'door' ? '门' : '窗' }}组件</div>
