<script>
import { computed, ref, watch } from 'vue'
import { editorState, requestSizeEdit, requestAssetReplace, requestAssetRestore, requestTextureApply, requestTextureUpload, requestPositionEdit, requestDoorToggle, requestWindowSlide, requestWindowOpen, requestDoorSlide, requestFrenchDoor } from '../../lib/editorState'
import { WALL_TEXTURES } from '../../lib/textures'

const MAT_SHORT = {
  'M_0014_DarkSalmon': 'Salmon',
  'M_0135_DarkGray': 'DarkGray',
  'M_0010_Snow': 'Snow',
  'Translucent_Glass_Gray': 'Glass'
}

export default {
  name: 'PanelProps',
  props: {
    catalog: { type: Object, default: null }
  },
  setup(props) {
    const sel = computed(() => editorState.selected)
    const state = editorState

    /** 当前模型能力开关（分类文件 meta.features）：doorOpen=原生门开合 / roof=屋顶开关 */
    const features = computed(() => {
      const cat = props.catalog
      return (cat && cat.meta && cat.meta.features) || {}
    })

    /** 原生推拉窗是否可滑（5 件式：外框+两扇框+两玻璃）；固定窗（2 件等）无滑钮 */
    const nativeSlideable = computed(() => {
      const s = editorState.selected
      return !!(s && s.kind === 'combo' && s.item.type === 'window' && (s.item.parts || []).length === 5)
    })

    /** 原生窗是否为「上悬外开窗」（顶部铰链）：当前模型 features.hopperTop 白名单内的窗，如 22 → W7/W8。
     * 注意：曾用部件厚度几何判型（size_z>0.5m），catalog 尺寸统一为米后永不命中 → 改用特征白名单。 */
    const nativeSwingOut = computed(() => {
      const s = editorState.selected
      if (!s || s.kind !== 'combo' || s.item.type !== 'window') return false
      const list = features.value.hopperTop
      return Array.isArray(list) && list.includes(s.item.id)
    })

    /** 当前外开窗是否平开中（按选中 key 匹配 editorState.windowSlide.dir='open'） */
    const nativeSwingOpen = computed(() => {
      const s = editorState.selected
      const key = s && s.kind === 'combo' ? s.item.id : ''
      return key === editorState.windowSlide.key && editorState.windowSlide.dir === 'open'
    })

    /** 外开窗 开/关 */
    function toggleNativeSwing() {
      const s = editorState.selected
      const key = s && s.kind === 'combo' ? s.item.id : ''
      if (!key) return
      requestWindowSlide(key, nativeSwingOpen.value ? '' : 'open')
    }

    /** 门是否可推拉（门内含两扇大尺寸 leaf frame；如模型 22 的门4）。单位为米（catalog 已 scale）：
     *  size_y > 0.4（≈ 40cm 高）、0.12 ≤ size_z ≤ 0.22、size_x > 0.001（厚板；玻璃 plane size_x=0 排除） */
    const doorSlideable = computed(() => {
      const s = editorState.selected
      if (!s || s.kind !== 'combo' || s.item.type !== 'door') return false
      const parts = s.item.parts || []
      let leafCount = 0
      for (const p of parts) {
        if (!p.size) continue
        const [sx, sy, sz] = p.size
        if (sy > 0.4 && sz >= 0.12 && sz <= 0.22 && sx > 0.001) leafCount++
        if (leafCount >= 2) return true
      }
      return false
    })

    /** 门是否为法式门（左右双扇绕外侧铰链平开；如模型 22 的门1/2/3）：含 size_z≈0.43 的门框特征部件，且不是可推拉门 */
    const doorSwingable = computed(() => {
      const s = editorState.selected
      if (!s || s.kind !== 'combo' || s.item.type !== 'door') return false
      if (doorSlideable.value) return false
      const parts = s.item.parts || []
      return parts.some((p) => p.size && Math.abs(p.size[2] - 0.43) < 0.1 && Math.abs(p.size[0]) > 1 && Math.abs(p.size[1]) > 1)
    })

    /** 当前法式门是否处于平开状态（按选中 key 匹配 editorState.frenchDoor.open） */
    const frenchOpen = computed(() => {
      const s = editorState.selected
      const key = s && s.kind === 'combo' ? s.item.id : ''
